def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c]==6:
                # infer from the matching position in a repeated 15-cell motif
                candidates=[grid[(r+15)%h][c], grid[(r+15)%h][(c+15)%w], grid[r][(c+15)%w], grid[(r+15)%h][(c+15)%w]]
                vals=[x for x in candidates if x!=6]
                if vals: out[r][c]=max(set(vals),key=vals.count)
    return out
